SourceCode.Declaration:
/// <summary>
/// Stock count control center: Check for duplicates - re-checks the selected stock count.
/// </summary>
class HSMobileOpsCountRefresh
{
}

Method.Source:
public static void main(Args _args)
{
    Common                 record = _args ? _args.record() : null;
    HSMobileOpsCountMaster master;

    // Count control center, by store: the selected store journal.
    if (record && record.TableId == tableNum(HSMobileOpsCountStoreJournal) && record.RecId)
    {
        HSMobileOpsCountStoreJournalEngine::refresh(record.RecId);
        HSMobileOpsCountRefresh::researchCaller(_args);
        return;
    }
    master = record;
    if (!master || !master.RecId)
    {
        throw error('Select a stock count first.');
    }
    if (HSMobileOpsCountControl::masterOf(master.RecId).Status == HSMobileOpsCountMasterStatus::Transferring)
    {
        throw error(strFmt('%1 is being transferred. Check it again once that is done.', master.MasterId));
    }
    HSMobileOpsCountControl::refresh(master.RecId);
    HSMobileOpsCountRefresh::researchCaller(_args);
}

/// <summary>
/// Reads the calling form's data again, keeping the selected rows.
/// </summary>
public static void researchCaller(Args _args)
{
    if (_args && _args.caller() is FormRun)
    {
        FormRun callerForm = _args.caller() as FormRun;
        int     i;
        for (i = 1; i <= callerForm.dataSourceCount(); i++)
        {
            callerForm.dataSource(i).research(true);
        }
    }
}
